<template><section class="difference-panel"><div class="toolbar"><strong>收货差异与处理</strong><el-button size="small" @click="load">刷新差异</el-button></div><p class="muted">短收、次品与超收、错货分别处理；差异处理说明不代替仓库实收或库存入账。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="!canRead" title="当前账号没有收货差异查询权限" type="info" :closable="false"/><el-table v-if="canRead" v-loading="loading" :data="rows" size="small" empty-text="暂无收货差异"><el-table-column label="入库单 / 原消息" min-width="240"><template slot-scope="{row}">{{ row.ticket_sn }}<div class="muted">{{ row.message_id }}</div></template></el-table-column><el-table-column label="差异类型 / 数量" min-width="160"><template slot-scope="{row}"><el-tag size="mini" type="warning">{{ kinds[row.difference_kind] }}</el-tag><div>差异 {{ row.difference_quantity }}</div><div class="muted">本次回传 {{ row.reported_quantity }}</div></template></el-table-column><el-table-column label="当前结果 / 原因" min-width="260"><template slot-scope="{row}"><el-tag size="mini" :type="['OPEN','WAITING'].includes(row.state)?'warning':'success'">{{ states[row.state] }}</el-tag><div class="muted">{{ row.reason }}</div><div v-if="row.resolution_reason">处理：{{ row.resolution_reason }}</div><div v-if="row.actor" class="muted">{{ row.actor }} · {{ row.update_time }}</div></template></el-table-column><el-table-column label="操作" width="110"><template slot-scope="{row}"><el-button type="text" @click="show(row)">{{ ['OPEN','WAITING'].includes(row.state)?'核对并处理':'查看结果' }}</el-button></template></el-table-column></el-table>
  <el-dialog title="核对采购收货差异" :visible.sync="visible" width="min(1000px,96vw)" append-to-body :close-on-click-modal="false"><div v-loading="detailLoading" v-if="current"><el-alert :title="guidance" type="info" :closable="false"/><el-descriptions :column="2" border size="small"><el-descriptions-item label="原入库单">{{ current.ticket_sn }}</el-descriptions-item><el-descriptions-item label="差异 / 当前结果">{{ kinds[current.difference_kind] }} · {{ states[current.state] }}</el-descriptions-item><el-descriptions-item label="本批原计划">{{ current.expected_quantity }}</el-descriptions-item><el-descriptions-item label="原回传消息">{{ current.message_id }}</el-descriptions-item></el-descriptions><el-table :data="current.lines" size="small"><el-table-column prop="sku" label="实际回传SKU" min-width="240"/><el-table-column prop="batch" label="回传批次" min-width="170"/><el-table-column prop="good" label="正品"/><el-table-column prop="bad" label="次品"/></el-table><el-button v-if="current.source_log_id" type="text" @click="$emit('interaction',current.ticket_sn,current.source_log_id)">查看原仓库回传</el-button><div v-if="canHandle&&['OPEN','WAITING'].includes(current.state)"><el-form label-position="top"><el-form-item label="处理方式"><el-select v-model="form.decision"><el-option v-for="item in decisions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="核对依据"><el-input v-model.trim="form.reason" type="textarea" maxlength="1000" show-word-limit placeholder="填写仓库核对结果、供应商协商依据或相关凭证"/></el-form-item></el-form><p class="muted">{{ form.decision==='REARRANGE'?'仅按当前实际短收创建新的待审核到货单；原实收、原库存及原采购计划保持可追溯。':form.decision==='KEEP_BAD'?'确认次品留库处理，不将次品改为正品，不再次增加库存。':'保留原回传及已确认事实，本次不会增加库存。' }}</p></div><p v-else>{{ current.resolution_reason }}</p><el-alert v-if="submitError" :title="submitError" type="error" :closable="false"/></div><span slot="footer"><el-button :disabled="busy" @click="visible=false">关闭</el-button><el-button v-if="current&&canHandle&&['OPEN','WAITING'].includes(current.state)" type="primary" :loading="busy" @click="submit">确认处理</el-button></span></el-dialog>
</section></template>
<script>
import { differences, differenceDetail, decideDifference } from '@/api/purchase/workspace'
import { checkPermi } from '@/utils/permission'
export default { props:{kind:{type:String,required:true},id:{type:Number,required:true},initialId:{type:[String,Number],default:''}},data:()=>({rows:[],loading:false,error:'',sequence:0,detailSequence:0,visible:false,current:null,detailLoading:false,busy:false,submitError:'',form:{decision:'WAIT_CORRECTION',reason:''},kinds:{SHORT:'最终短收',QUALITY:'次品',OVER:'超收',WRONG_SKU:'错货',LATE:'迟到回传额度冲突'},states:{OPEN:'待处理',WAITING:'等待仓库更正',RESOLVED:'已处理',REJECTED:'已拒收',CORRECTED:'后续回传已更正'}}),computed:{canRead(){return checkPermi(['warehouse:poInfo:differenceQuery'])},canHandle(){return checkPermi(['warehouse:poInfo:differenceReview'])},decisions(){if(!this.current)return[];const kind=this.current.difference_kind;const rows=[{value:'WAIT_CORRECTION',label:'等待仓库核对或更正'}];if(kind==='SHORT'&&checkPermi(['warehouse:poInfo:receive']))rows.unshift({value:'REARRANGE',label:'按当前短收差额补建到货单'});if(kind==='QUALITY')rows.unshift({value:'KEEP_BAD',label:'确认次品留库处理'});if(['OVER','WRONG_SKU','LATE'].includes(kind))rows.push({value:'REJECT',label:'确认拒收本次异常回传'});return rows},guidance(){return !this.current?'':this.current.difference_kind==='SHORT'?'最终短收保留原计划；已实收按原批次入账，补建数量仍受采购剩余额度校验。':this.current.difference_kind==='QUALITY'?'次品质量与库存入账分别核对；确认留库前必须完成本次次品入账。':'本次异常回传尚未确认为实收或库存。核对后等待更正或确认拒收；已确认的其他回传不受影响。'}},watch:{id:{immediate:true,handler(){this.load()}}},beforeDestroy(){this.sequence++;this.detailSequence++},methods:{async load(){if(!this.canRead)return;const seq=++this.sequence;this.loading=true;this.error='';try{const rows=(await differences({kind:this.kind,id:this.id})).data;if(seq!==this.sequence)return;this.rows=rows||[];const initial=this.rows.find(r=>Number(r.id)===Number(this.initialId)&&['OPEN','WAITING'].includes(r.state));if(initial&&!this.visible)this.show(initial)}catch(_){if(seq===this.sequence)this.error='收货差异加载失败，请刷新重试'}finally{if(seq===this.sequence)this.loading=false}},async show(row){const seq=++this.detailSequence;this.current=null;this.visible=true;this.detailLoading=true;this.submitError='';try{const r=(await differenceDetail(row.id)).data;if(seq===this.detailSequence){this.current=r;this.form={decision:'WAIT_CORRECTION',reason:''}}}finally{if(seq===this.detailSequence)this.detailLoading=false}},async submit(){if(this.busy||!this.current)return;if(!this.form.reason)return this.$message.warning('请填写核对依据');this.busy=true;this.submitError='';try{const r=(await decideDifference(this.current.id,{...this.form,control_version:this.current.control_version})).data;this.visible=false;await this.load();this.$emit('changed',r);this.$message.success(r.receipt_id?'已补建待审核到货单，请核对后审核':'差异处理结果已保存')}catch(e){this.submitError=e.message||'处理未完成，请刷新差异记录核对'}finally{this.busy=false}}}}
</script>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:18px 0}.muted{font-size:12px;color:#7a899d;line-height:1.8;overflow-wrap:anywhere}.el-alert{margin:12px 0}.el-descriptions{margin:16px 0}.el-form{margin-top:18px}.el-select{width:100%}</style>
